export class Point {
  x: number;
  y: number;
  constructor(x: number, y: number) { this.x = x; this.y = y; }
  norm(): number { return this.x * this.x + this.y * this.y; }
}
export interface Pair { first: number; second: number }
export function makePoint(i: number): Point { return new Point(i, i + 1); }
export function makePair(i: number): Pair { return { first: i, second: i + 1 }; }
export const which = "source";
